// Import pdfjsLib from pdfjs-dist
import * as pdfjsLib from 'pdfjs-dist';

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

// Function to extract keywords from the parsed text
const extractKeywords = (text) => {
  const words = text
    .toLowerCase()
    .match(/\b\w+\b/g); // Match words

  const stopWords = new Set(['the', 'is', 'in', 'and', 'to', 'with', 'a', 'of', 'for', 'on', 'as', 'it', 'this', 'that', 'by', 'an']); // Extend this set as needed
  const wordFreq = {};

  // Count frequency of each word
  words.forEach(word => {
    if (!stopWords.has(word)) {
      wordFreq[word] = (wordFreq[word] || 0) + 1;
    }
  });

  // Sort keywords by frequency and return the top 20
  const sortedKeywords = Object.entries(wordFreq)
    .sort(([, a], [, b]) => b - a)
    .map(([word]) => word);

  return sortedKeywords.slice(0, 20); // Return top 20 keywords
};

// Function to group keywords based on their first letter
const groupKeywords = (keywords) => {
  const keywordGroups = {};

  keywords.forEach(keyword => {
    const firstLetter = keyword[0]; // Grouping by first letter
    if (!keywordGroups[firstLetter]) {
      keywordGroups[firstLetter] = [];
    }
    keywordGroups[firstLetter].push(keyword);
  });

  return keywordGroups;
};

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      try {
        const typedArray = new Uint8Array(reader.result);
        const pdf = await pdfjsLib.getDocument(typedArray).promise;

        if (!pdf || !pdf.numPages) {
          reject(new Error('Failed to load PDF document or no pages found.'));
          return;
        }

        let parsedText = '';

        // Loop through all the pages
        for (let i = 1; i <= pdf.numPages; i++) {  // Start from page 1
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();

          // Extract text from each page
          const pageText = textContent.items.map((item) => item.str).join(' ');
          parsedText += pageText + '\n';
        }

        // Extract and group keywords
        const keywords = extractKeywords(parsedText);
        const groupedKeywords = groupKeywords(keywords);

        resolve({ keywords, groupedKeywords }); // Return both keywords and grouped keywords
      } catch (error) {
        reject(error); // Catch any errors during parsing
      }
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

export { parsePDF };
